def sources(key):
 return references.get(key,[('U.S. Small Business Administration. (n.d.). Manage your business.','https://www.sba.gov/counseling/manage-your-business/'),('National Institute of Standards and Technology. (n.d.). AI Risk Management Framework.','https://www.nist.gov/itl/ai-risk-management-framework')])
def foundation_markup(key):
 u=units[key];questions=u[5];parts=[]
 for i,(heading,body) in enumerate(u[:3]):
  q,opts,answer,why=questions[i]
  parts.append(f'<section class="unit-step"><span class="eyebrow">Learn & apply · {i+1}</span><h3>{E(heading)}</h3><p>{E(body)}</p><fieldset class="unit-check" data-unit-question="{i}"><legend>Check your understanding</legend><p>{E(q)}</p>'+''.join(f'<button type="button" data-choice="{j}" aria-pressed="false">{E(t)}</button>' for j,t in enumerate(opts))+'<p class="unit-feedback" role="status"></p></fieldset></section>')
 data=[{'answer':q[2],'why':q[3]} for q in questions]
 return '<section id="foundation-unit" class="foundation-unit"><span class="eyebrow">Published foundation lesson</span><h2>Learn it. Try it. Make it yours.</h2><p class="unit-note">This introductory lesson is ready to use. The six-module curriculum below shows the larger course being developed. Take any course independently.</p>'+''.join(parts)+f'<section class="unit-example"><span class="eyebrow">Worked example · Illustrative scenario</span><h3>See the idea in action.</h3><p>{E(u[3])}</p></section><section class="unit-project"><span class="eyebrow">Apply & create</span><h3>Build a small result.</h3><p>{E(u[4])}</p><details><summary>Review your work against these criteria →</summary><ul><li>Clarity: Can another person understand your goal and steps?</li><li>Evidence: Are your important claims checked against the source?</li><li>Usefulness: Does your result work in the actual situation?</li><li>Transfer: What would you change for a different person or constraint?</li></ul><p>Ask someone to try your result when practical. Use their experience to revise one choice. The three questions check understanding; the project checks what you can actually do.</p></details><label for="unit-notes">Your decisions and application notes</label><textarea id="unit-notes" data-plan="unit-notes" placeholder="Describe your result, evidence, and next revision."></textarea><p class="small">Notes stay in this browser when storage is available. Include them in your downloaded learning plan below.</p><div class="reader-actions"><button type="button" class="platinum" id="check-unit">Review my answers →</button></div><p id="unit-result" role="status"></p></section><section class="unit-sources"><h3>Reference shelf.</h3><p>Original InAct explanation and illustrative examples. These primary sources support further study; platform terms should be checked again before use. References use an APA-style organization, date, and title. Sources without a verified publication date are marked n.d.</p><ul>'+''.join(f'<li><a href="{url}" target="_blank" rel="noopener noreferrer">{E(label)} ↗</a></li>' for label,url in sources(key))+'</ul></section></section><script type="application/json" id="course-unit-data">'+json.dumps(data).replace('<','\\u003c')+'</script>'
